import type { EngineInterface as Engine, Register } from 'claude-code'

import type { Feeling, Helper, Mood, StyleName } from '../types'

const TICK_MS = 400
const HAPPY_MS = 6000
const OOPS_MS = 5000
const SLEEP_AFTER_MS = 60000
const HELPER_DONE_MS = 4000
const HELPER_STALE_MS = 180000
const MAX_HELPERS = 4

// Text bunny, used where there is no Raster (the desktop app). Two frames per mood.
const FACES: Record<Mood, [string, string]> = {
  idle: [`(='.'=)`, `(-'.'-)`],
  sleep: [`(-.-)`, `(-_-)`],
  think: [`(='.'=)`, `(=°.°=)`],
  work: [`(>'.'>)`, `(<'.'<)`],
  oops: [`(;'.';)`, `(T'.'T)`],
  happy: [`(^'.'^)`, `(^o.o^)`],
}
const EARS: Record<Mood, [string, string]> = {
  idle: [`(\\_/)`, `(\\_/)`],
  sleep: [`(\\_/)`, `(\\_/)`],
  think: [`(\\_/)`, `(/_/)`],
  work: [`(\\_/)`, `(\\_/)`],
  oops: [`(\\_/)`, `(\\_/)`],
  happy: [`(\\_/)`, `(\\_/)`],
}
const COLORS: Record<Mood, string | undefined> = {
  idle: undefined,
  sleep: undefined,
  think: 'yellow',
  work: 'cyan',
  oops: 'red',
  happy: 'green',
}

// Raster bunny: pixel art, two pixels per terminal row (half blocks).
// Legend: . empty, L outline, W fur, G shade, P inner ear, C cheek, N nose,
// K eye, B tear, Y sparkle. Row counts are odd: the canvas adds one spare row for the hop.
type Spot = [row: number, col: number]
type Style = {
  rows: string[]
  eyes: Spot[]
  smile: Spot[]
  frown: Spot[]
  sparks: [Spot[], Spot[]]
}

const STYLES: Record<StyleName, Style> = {
  chibi: {
    rows: [
      '...LL...LL...',
      '..LWWL.LWWL..',
      '..LWPL.LPWL..',
      '..LWPWLWPWL..',
      '.LWWWWWWWWWL.',
      'LWWWWWWWWWWWL',
      'LWWKWWWWWKWWL',
      'LWCWWWNWWWCWL',
      '.LWWWWWWWWWL.',
      '..LLLWWWLLL..',
      '..LWWLWLWWL..',
      '..LGWWWWWGL..',
      '...LLL.LLL...',
    ],
    eyes: [[6, 3], [6, 9]],
    smile: [[8, 5], [8, 7], [9, 6]],
    frown: [[8, 6]],
    sparks: [[[0, 0], [2, 12]], [[2, 0], [0, 12]]],
  },
  sit: {
    rows: [
      '........LL.LL...',
      '.......LWWLWWL..',
      '.......LWPLWPL..',
      '.......LWWLWWWL.',
      '.......LWWWWWWWL',
      '....LLLLWWWWWWWL',
      '..LLWWWLWWKWWKWL',
      '.LWWWWWLWWWWWWWN',
      '.LLWWWWWLWWWWWL.',
      'LWWLWWWWWLLLLL..',
      'LWWLWWWWWWWWL...',
      '.LLGGWWWWWLWWL..',
      '..LLLLLLLLLLLL..',
    ],
    eyes: [[6, 10], [6, 13]],
    smile: [],
    frown: [],
    sparks: [[[0, 2], [1, 15]], [[3, 2], [0, 15]]],
  },
  loaf: {
    rows: [
      '..........LLLL..',
      '....LLLLLLWWWWL.',
      '..LLWPPPPLWWWWWL',
      '.LWWLLLLLWWKWKWL',
      'LWWWWWWWWWWWWWWN',
      'LWWWWWWWWWWWWWWL',
      'LWWWWWWWWWWWWWL.',
      '.LGGWWWWWWWWGGL.',
      '..LLLLLLLLLLLL..',
    ],
    eyes: [[3, 11], [3, 13]],
    smile: [],
    frown: [],
    sparks: [[[0, 2], [1, 0]], [[1, 1], [0, 3]]],
  },
}

const PALETTE: Record<string, number> = {
  L: 0x8a8398,
  W: 0xf4f0f2,
  G: 0xc9c2cf,
  P: 0xf4a6c0,
  N: 0xe87ba0,
  C: 0xf8c0d0,
  K: 0x2b2433,
  B: 0x6cb4ff,
  Y: 0xffd84d,
}
const DEFAULT_COLOR = 0x01000000

// Draws one mood and frame onto a copy of the style's pixels. Returns the grid
// and whether the sprite lifts one pixel (the bounce of working and happy).
const paint = (style: Style, mood: Mood, n: number): { grid: string[][]; isUp: boolean } => {
  const grid = style.rows.map(row => row.split(''))
  const put = (spots: Spot[], ch: string) => {
    for (const [r, c] of spots) if (grid[r]?.[c] !== undefined) grid[r]![c] = ch
  }
  // Moves each eye by (dr, dc) onto fur or cheek, and gives it back where it was.
  const lookAt = (dr: number, dc: number) => {
    for (const [r, c] of style.eyes) {
      const target = grid[r + dr]?.[c + dc]
      if (target === 'W' || target === 'C') {
        grid[r]![c] = 'W'
        grid[r + dr]![c + dc] = 'K'
      }
    }
  }
  const odd = n % 2 === 1

  if (mood === 'sleep' || (mood === 'idle' && n % 12 === 11)) put(style.eyes, 'L')
  if (mood === 'think') lookAt(-1, odd ? -1 : 0)
  if (mood === 'work') lookAt(0, odd ? 1 : -1)
  if (mood === 'oops') {
    for (const [r, c] of style.eyes) {
      const dr = odd ? 2 : 1
      if (grid[r + dr]?.[c] === 'W' || grid[r + dr]?.[c] === 'C') grid[r + dr]![c] = 'B'
    }
    put(style.frown, 'K')
  }
  if (mood === 'happy') {
    put(style.smile, 'K')
    put(style.sparks[odd ? 1 : 0], 'Y')
  }

  return { grid, isUp: odd && (mood === 'work' || mood === 'happy') }
}

// Packs the sprite as `Raster` cells: one `▀`/`▄` per two pixels, row-major.
const spriteCells = (style: Style, mood: Mood, n: number): string => {
  const { grid, isUp } = paint(style, mood, n)
  const width = grid[0]!.length
  // The sprite has an odd number of rows, so the canvas has one spare pixel row
  // above it at rest. A hop moves the sprite into it.
  const height = grid.length + 1
  const shift = isUp ? 0 : 1
  const pixel = (y: number, x: number): number | undefined => {
    const ch = grid[y - shift]?.[x]
    return ch === undefined || ch === '.' ? undefined : PALETTE[ch]
  }
  const words = new Uint32Array(width * (height / 2) * 3)
  let i = 0
  for (let r = 0; r < height / 2; r++) {
    for (let c = 0; c < width; c++) {
      const up = pixel(2 * r, c)
      const down = pixel(2 * r + 1, c)
      // Two equal pixels are a full block with the default background: a cell
      // with a coloured background paints a grey bar to its left in the terminal.
      const [glyph, fg, bg] =
        up === undefined && down === undefined
          ? [0x20, DEFAULT_COLOR, DEFAULT_COLOR]
          : up === undefined
            ? [0x2584, down!, DEFAULT_COLOR]
            : up === down
              ? [0x2588, up, DEFAULT_COLOR]
              : [0x2580, up, down ?? DEFAULT_COLOR]
      words[i++] = glyph!
      words[i++] = fg!
      words[i++] = bg!
    }
  }
  return new Uint8Array(words.buffer).toBase64()
}

const decay = (f: Feeling, now: number): Feeling => {
  const age = now - f.since
  const isDone =
    (f.mood === 'happy' && age > HAPPY_MS) || (f.mood === 'oops' && age > OOPS_MS)
  if (isDone) return { mood: 'idle', label: '', since: now }
  if (f.mood === 'idle' && age > SLEEP_AFTER_MS) return { mood: 'sleep', label: '', since: now }
  return f
}

const shorten = (text: string, max = 48): string => {
  const one = text.replace(/\s+/g, ' ').trim()
  return one.length > max ? `${one.slice(0, max - 1)}…` : one
}

// A small text bunny for each running subagent: ears, then a face for its mood.
const helperFace = (mood: Mood, odd: boolean): string => {
  if (mood === 'happy') return odd ? '(^o^)' : '(^.^)'
  if (mood === 'oops') return odd ? '(T.T)' : '(;.;)'
  return odd ? '(>.>)' : '(<.<)'
}
const EARS_HELPER = '(\\_/)'
const HELPER_COLORS: Partial<Record<Mood, string>> = { work: 'cyan', happy: 'green', oops: 'red' }

const baseName = (path: string): string => path.split('/').pop() ?? path

// What a tool call is doing, in a few words, from the tool's own arguments.
const describeTool = (tool: string, input: Record<string, unknown>): string => {
  const str = (key: string): string => (typeof input[key] === 'string' ? (input[key] as string) : '')
  switch (tool) {
    case 'Read':
      return `reading ${baseName(str('file_path'))}`
    case 'Edit':
    case 'Write':
    case 'NotebookEdit':
      return `editing ${baseName(str('file_path'))}`
    case 'Bash':
      return shorten(`$ ${str('description') || str('command')}`)
    case 'Grep':
      return shorten(`searching for ${str('pattern')}`)
    case 'Glob':
      return shorten(`finding ${str('pattern')}`)
    case 'Task':
    case 'Agent':
      return shorten(`delegating: ${str('description')}`)
    case 'WebFetch':
      return shorten(`fetching ${str('url')}`)
    case 'WebSearch':
      return shorten(`searching the web: ${str('query')}`)
    default:
      return `using ${tool}`
  }
}

const upsert = (list: Helper[], helper: Helper): Helper[] =>
  [...list.filter(one => one.id !== helper.id), helper].slice(-8)

// Subagents run at the same time, so a change retries when another one wrote first.
async function patchHelpers($: Engine, change: (list: Helper[]) => Helper[]): Promise<void> {
  for (let attempt = 0; attempt < 5; attempt++) {
    const held = await $.state.get({ plugin: 'bunny', key: 'helpers' } as const)
    const done = await $.state.set(
      { plugin: 'bunny', key: 'helpers' } as const,
      change(held.value ?? []),
      { ifVersion: held.version },
    )
    if (done.isSet) return
  }
}

export const register: Register = on => {
  let frameNo = 0

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'bunny',
      description: 'Show or hide the bunny, or pick its style: /bunny [chibi|sit|loaf]',
    })

    // The style is kept between sessions.
    const saved = await $.store.get('style')
    if (saved === 'chibi' || saved === 'sit' || saved === 'loaf') {
      await $.state.set({ plugin: 'bunny', key: 'style' } as const, saved)
    }

    $.clock.every(TICK_MS, async () => {
      const now = await $.clock.now()
      const held = await $.state.get({ plugin: 'bunny', key: 'feeling' } as const)
      if (held.value !== undefined) {
        const decayed = decay(held.value, now)
        if (decayed !== held.value) {
          await $.state.set({ plugin: 'bunny', key: 'feeling' } as const, decayed)
        }
      }
      const helpers = await $.state.get({ plugin: 'bunny', key: 'helpers' } as const)
      const list = helpers.value ?? []
      const fresh = list.filter(h => now - h.since < (h.mood === 'happy' ? HELPER_DONE_MS : HELPER_STALE_MS))
      if (fresh.length !== list.length) {
        await patchHelpers($, current => current.filter(h => fresh.some(one => one.id === h.id)))
      }
      frameNo = (frameNo + 1) % 1000
      await $.state.set({ plugin: 'bunny', key: 'frame' } as const, frameNo)
    })

    return next(e)
  })

  on('command.run', { command: 'bunny' }, async ($, e) => {
    const arg = e.args.trim()
    const held = await $.state.get({ plugin: 'bunny', key: 'isHidden' } as const)
    const hidden = held.value === true

    if (arg === 'chibi' || arg === 'sit' || arg === 'loaf') {
      await $.state.set({ plugin: 'bunny', key: 'style' } as const, arg)
      await $.store.set('style', arg)
      await $.state.set({ plugin: 'bunny', key: 'isHidden' } as const, false)

      return { text: `Bunny style: ${arg} :3 (remembered)` }
    }
    if (arg !== '') {
      return { text: 'Usage: /bunny [chibi|sit|loaf]. With no argument it shows or hides the bunny.' }
    }

    await $.state.set({ plugin: 'bunny', key: 'isHidden' } as const, !hidden)

    return { text: hidden ? 'Bunny is back :3' : 'Bunny is hiding.' }
  })

  on('prompt.submit', async ($, e, next) => {
    await $.state.set({ plugin: 'bunny', key: 'feeling' } as const, { mood: 'think', label: 'twitching ears', since: await $.clock.now() })

    return next(e)
  })

  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)
    const id = started.agentId

    if (started.deny === undefined && id !== undefined) {
      const now = await $.clock.now()
      const name = e.name ?? e.description
      await patchHelpers($, list =>
        upsert(list, { id, name, mood: 'work', label: shorten(e.description), since: now }),
      )
    }

    return started
  })

  on('tool.call', async ($, e, next) => {
    const now = await $.clock.now()
    const label = describeTool(e.tool, e as unknown as Record<string, unknown>)
    const id = e.agentId

    if (id !== undefined) {
      // A subagent's call moves its own bunny, not the main one.
      await patchHelpers($, list =>
        upsert(list, { id, name: list.find(h => h.id === id)?.name ?? 'helper', mood: 'work', label, since: now }),
      )
      const ran = await next(e)
      if (ran.deny === undefined && ran.isError === true) {
        const failedAt = await $.clock.now()
        await patchHelpers($, list =>
          list.map(h => (h.id === id ? { ...h, mood: 'oops', label: `${e.tool} failed`, since: failedAt } : h)),
        )
      }

      return ran
    }

    await $.state.set({ plugin: 'bunny', key: 'feeling' } as const, { mood: 'work', label, since: now })
    const ran = await next(e)

    if (ran.deny === undefined && ran.isError === true) {
      await $.state.set({ plugin: 'bunny', key: 'feeling' } as const, { mood: 'oops', label: `${e.tool} failed`, since: await $.clock.now() })
    }

    return ran
  })

  on('turn.complete', async ($, e, next) => {
    const now = await $.clock.now()
    const id = e.agentId

    if (id !== undefined) {
      const mood: Mood = e.reason === 'answer' ? 'happy' : 'oops'
      await patchHelpers($, list => list.map(h => (h.id === id ? { ...h, mood, label: 'done', since: now } : h)))

      return next(e)
    }

    const seconds = Math.round(e.durationMs / 1000)
    const feeling: Feeling =
      e.reason === 'answer'
        ? { mood: 'happy', label: `all done in ${seconds}s!`, since: now }
        : e.reason === 'aborted'
          ? { mood: 'idle', label: '', since: now }
          : { mood: 'oops', label: 'something went wrong', since: now }
    await $.state.set({ plugin: 'bunny', key: 'feeling' } as const, feeling)

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const hid = await $.state.get({ plugin: 'bunny', key: 'isHidden' } as const)
    if (e.props.hasSurvey || hid.value === true) {
      return next(e)
    }

    const { Box, Text } = $.ui.resolve(e)
    const feeling = await $.state.get({ plugin: 'bunny', key: 'feeling' } as const)
    const frame = await $.state.get({ plugin: 'bunny', key: 'frame' } as const)
    const p: Feeling = feeling.value ?? { mood: 'idle', label: '', since: 0 }
    const f = (frame.value ?? 0) % 2
    if (e.surface === 'terminal') {
      const { Raster } = $.ui.resolve(e)
      const styled = await $.state.get({ plugin: 'bunny', key: 'style' } as const)
      const name: StyleName = styled.value ?? 'chibi'
      const style = STYLES[name]
      const n = frame.value ?? 0
      const zzz = p.mood === 'sleep' ? (n % 2 ? 'z' : 'Z') : ''
      const crew = await $.state.get({ plugin: 'bunny', key: 'helpers' } as const)
      const helpers = crew.value ?? []
      const shown = helpers.slice(-MAX_HELPERS)

      return (
        <Box flexDirection="row">
          <Raster
            key="bunny"
            columns={style.rows[0]!.length}
            rows={(style.rows.length + 1) / 2}
            cells={spriteCells(style, p.mood, n)}
          />
          <Box flexDirection="column">
            <Text dimColor>  {zzz}{p.label}</Text>
            {shown.length > 0 && (
              <Box flexDirection="row">
                <Text>  </Text>
                {shown.map((helper, i) => {
                  const odd = (n + i) % 2 === 1
                  const hop = odd && helper.mood !== 'oops' ? ' ' : ''
                  const color = HELPER_COLORS[helper.mood]

                  return (
                    <Box key={`helper-${helper.id}`} flexDirection="row">
                      <Text>   </Text>
                      <Box flexDirection="column">
                        <Text color={color}>{hop}{EARS_HELPER}</Text>
                        <Text color={color}>{hop}{helperFace(helper.mood, odd)}</Text>
                        <Text dimColor>{helper.name.length > 7 ? `${helper.name.slice(0, 6)}…` : helper.name}</Text>
                      </Box>
                    </Box>
                  )
                })}
                {helpers.length > shown.length && <Text dimColor> +{helpers.length - shown.length}</Text>}
              </Box>
            )}
          </Box>
        </Box>
      )
    }

    const crew = await $.state.get({ plugin: 'bunny', key: 'helpers' } as const)
    const extra = (crew.value ?? []).length > 0 ? ` (+${(crew.value ?? []).length} helpers)` : ''
    const hop = p.mood === 'work' || p.mood === 'happy' ? (f ? '  ' : '') : ''
    const color = COLORS[p.mood]
    const zzz = p.mood === 'sleep' ? (f ? ' z' : ' Z') : ''
    const bottom = f ? ` (")_(")` : `(")_(")`

    return (
      <Box flexDirection="row">
        <Box flexDirection="column">
          <Text color={color}>{hop}{EARS[p.mood][f]}</Text>
          <Text color={color}>{hop}{FACES[p.mood][f]}{zzz}</Text>
          <Text color={color}>{hop}{bottom}</Text>
        </Box>
        <Text dimColor>  {p.label}{extra}</Text>
      </Box>
    )
  })
}

