export type Mood = 'idle' | 'sleep' | 'think' | 'work' | 'oops' | 'happy'
export type StyleName = 'chibi' | 'sit' | 'loaf'
export type Helper = { id: string; name: string; mood: Mood; label: string; since: number }
export type Feeling = { mood: Mood; label: string; since: number }

declare module 'claude-code' {
  interface PluginState {
    bunny: { feeling: Feeling; frame: number; isHidden: boolean; style: StyleName; helpers: Helper[] }
  }
}
